xql_query:
// ============================================================
// Rule: AWS_Instance Accessed via SSM
// Vendor: AWS
// Objective:
// Detect activity associated with AWS_Instance Accessed via SSM.
// Severity: SEV_040_HIGH
// Category: LATERAL_MOVEMENT
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1108 - Redundant Access

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: evitar perda de eventos por variação de caixa em campos textuais (ex.: eventName)
config case_sensitive = false

// Fonte de dados: logs brutos do AWS (CloudTrail)
// O dataset 'amazon_aws_raw' contém eventos de auditoria de serviços AWS, incluindo AWS Systems Manager (SSM).
| dataset = amazon_aws_raw

// Filtro: restringe aos eventos do serviço AWS SSM
| filter eventSource = "ssm.amazonaws.com"

// Filtro: monitora início de sessão via SSM Session Manager
// eventName = "StartSession" indica abertura de sessão remota em um target (ex.: instância EC2)
| filter eventName = "StartSession"

// Extração: captura o principalId do executor (userIdentity.principalId)
// Esse campo costuma conter informação suficiente para identificar o usuário/entidade executora.
| alter principal_raw = to_json_string(useridentity) -> principalId

// Normalização: extrai um identificador do usuário a partir do principalId
// Em alguns formatos, o principalId pode vir como "ID:email" ou "ID:nome".
// Aqui dividimos por ":" e pegamos o segundo elemento (índice 1).
| alter user_email = arrayindex(split(to_string(principal_raw), ":"), 1)

// Extração: identifica o target da sessão (instância/alvo)
// requestParameters.target normalmente contém o instance-id (ex.: i-xxxxxxxxxxxx)
| alter instance_id = json_extract_scalar(to_json_string(requestParameters), "$.target")

// Saída final: campos recomendados para auditoria e alerta/correlação
| fields
    _time,      // Timestamp no XSIAM
    eventTime,  // Timestamp original do CloudTrail
    eventName,  // Ação executada (StartSession)
    user_email, // Usuário/identificador extraído do principalId
    instance_id // Alvo da sessão (ex.: instance-id)
